-- ==== 20261012000027_review_source.sql
-- Review request cards: where a review started, for the admin only.
--
-- * public.reviews.source: null (the default: the profile, a search, a shared page link) or 'card' (the person
--   arrived through the trader's review link or QR card, /r/<slug>, which lands on the form with ?ref=card).
--   Recorded so the admin can spot a run of trader-driven reviews. It changes no scoring and no automatic flag.
-- * public.submit_review: the 000021 body, plus the source. It comes in the same jsonb as the answers
--   (p ->> 'source'); anything other than 'card' is stored as null. Same signature, so the service-role-only
--   grants carry over; they're restated below as in 000021. edit_review is unchanged: an edit keeps the source.
-- * private.admin_review_json: gains "source", so the admin's moderation queues (held reviews, under check, flags,
--   proofs) can say "via review card". Nothing public reads the column: review_public and provider_my_reviews
--   name their columns, and the table has no grants for anon or authenticated.
-- Re-runnable.

alter table public.reviews add column if not exists source text check (source in ('card'));

-- ---------------------------------------------------------------- submit (000021 body + source)
create or replace function public.submit_review(p_uid uuid, p jsonb, p_device_hash text) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := p_uid;
  v_provider uuid;
  v_block text;
  f record;
  v_id uuid;
  v_status public.review_status;
begin
  if v_uid is null then
    raise exception 'not_member';
  end if;
  begin
    v_provider := (p ->> 'provider_id')::uuid;
  exception when others then
    v_provider := null;
  end;
  -- One posting at a time per person, so a double tap cannot slip two reviews past the 24-hour rule.
  perform pg_advisory_xact_lock(hashtext('submit_review:' || v_uid::text));

  v_block := private.review_block_reason(v_uid, v_provider);
  if v_block is not null then
    raise exception '%', v_block;
  end if;
  select * into f from private.review_fields(v_provider, p);

  begin
    insert into public.reviews (provider_id, reviewer_id, category_id, job_month, value_band, on_time, on_price,
                                quality, tidy, use_again, comment, status, device_hash, source)
    values (v_provider, v_uid, f.category_id, f.job_month, f.value_band, f.on_time, f.on_price,
            f.quality, f.tidy, f.use_again, f.comment,
            -- Email-only accounts (the weaker check) wait for the admin; Google and phone accounts publish.
            case when private.sign_in_kind(v_uid) = 'email' then 'pending' else 'published' end::public.review_status,
            nullif(p_device_hash, ''),
            -- Only the one known value; anything else (or nothing) is no source.
            case when p ->> 'source' = 'card' then 'card' end)
    returning id into v_id;
  exception when unique_violation then
    raise exception 'already_reviewed';
  end;

  perform private.run_review_flags(v_id);
  select status into v_status from public.reviews where id = v_id;
  return jsonb_build_object('id', v_id, 'status', v_status);
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array['public.submit_review(uuid, jsonb, text)'] loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end $$;

-- ---------------------------------------------------------------- admin read (000008 body + source)
-- One review as the admin sees it (no device hash; the reviewer's name and account age instead).
create or replace function private.admin_review_json(p_review uuid) returns jsonb
language sql stable security definer set search_path = ''
as $$
  select jsonb_build_object(
    'id', r.id, 'status', r.status, 'created_at', r.created_at, 'edited_at', r.edited_at,
    'job_month', r.job_month, 'value_band', r.value_band, 'on_time', r.on_time, 'on_price', r.on_price,
    'quality', r.quality, 'tidy', r.tidy, 'use_again', r.use_again, 'comment', r.comment,
    'category_name', c.name, 'provider_slug', p.slug, 'business_name', p.business_name,
    'reviewer_name', coalesce(pr.display_name, 'Deleted account'), 'account_created_at', u.created_at,
    'reviewer_review_count', (select count(*) from public.reviews x where x.reviewer_id = r.reviewer_id),
    'source', r.source
  )
  from public.reviews r
  join public.providers p on p.id = r.provider_id
  join public.categories c on c.id = r.category_id
  left join public.profiles pr on pr.user_id = r.reviewer_id
  left join auth.users u on u.id = r.reviewer_id
  where r.id = p_review;
$$;
revoke execute on function private.admin_review_json(uuid) from public, anon, authenticated;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000027', 'review_source') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
begin
  if not exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = 'reviews' and column_name = 'source') then
    raise exception 'Review source check failed: column public.reviews.source is missing';
  end if;
  if position('source' in pg_get_functiondef('public.submit_review(uuid, jsonb, text)'::regprocedure)) = 0 then
    raise exception 'Review source check failed: submit_review does not record the source';
  end if;
  if position('source' in pg_get_functiondef('private.admin_review_json(uuid)'::regprocedure)) = 0 then
    raise exception 'Review source check failed: the admin review view does not show the source';
  end if;
  if has_function_privilege('anon', 'public.submit_review(uuid, jsonb, text)', 'execute')
     or has_function_privilege('authenticated', 'public.submit_review(uuid, jsonb, text)', 'execute')
     or not has_function_privilege('service_role', 'public.submit_review(uuid, jsonb, text)', 'execute') then
    raise exception 'Review source check failed: submit_review is no longer service role only';
  end if;
end
$verify$;

commit;

select 'Review card database changes applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000027')) as migrations_recorded;
